## Design Note

**Data structures:** Global character offset counter; a state machine (`between`, `top_string`, `top_number`, `top_literal`, `top_term`, `string`, `number`, `literal`, `escape`, `unicode`); a stack of container contexts (`array`/`object` with expectation markers); a character-list buffer for the current top-level value. Buffer size is checked incrementally (O(1) per char). Decoding uses `json.loads` once per completed value.

**Complexity:** O(n) total time, n = total characters fed. Each character is examined exactly once; the buffer is appended to (never rescanned). `json.loads` is called once per completed top-level value.

**Concurrency:** Single-connection, single-threaded. No locks needed.

---

### solution.py
```python
"""Incremental JSON stream splitter for log ingestion."""
import json
from typing import Any


class JSONStreamError(ValueError):
    def __init__(self, msg: str = "", *, offset: int = 0):
        super().__init__(msg)
        self.offset = offset


class IncompleteJSONError(JSONStreamError):
    def __init__(self, msg: str = "", *, offset: int = 0):
        super().__init__(msg, offset=offset)


class BufferLimitError(JSONStreamError):
    def __init__(self, msg: str = "", *, offset: int = 0):
        super().__init__(msg, offset=offset)


_WHITESPACE = frozenset(" \t\n\r")
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


class JSONStreamDecoder:
    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if not isinstance(max_buffer, int) or isinstance(max_buffer, bool) or max_buffer < 1:
            raise ValueError("max_buffer must be an integer >= 1")
        self._max_buffer = max_buffer
        self._offset = 0
        self._state = "between"
        self._stack: list[str] = []
        self._buffer: list[str] = []
        self._buffer_start = 0
        self._buffer_size = 0
        self._closed = False
        self._errored = False
        # number sub-state: 0=initial, 1=after_minus, 2=after_zero, 3=after_int,
        # 4=after_digits, 5=after_dot, 6=after_frac, 7=after_exp, 8=after_exp_sign,
        # 9=after_exp_digits
        self._num_state = 0
        # literal tracking
        self._lit_target = ""
        self._lit_pos = 0
        # escape tracking
        self._escape_target = ""
        self._unicode_count = 0

    def feed(self, chunk: str) -> list[Any]:
        if self._errored:
            raise JSONStreamError("decoder is in error state", offset=self._offset)
        if self._closed:
            raise JSONStreamError("decoder is closed", offset=self._offset)
        if not isinstance(chunk, str):
            raise TypeError(f"expected str, got {type(chunk).__name__}")
        if chunk == "":
            return []
        results: list[Any] = []
        for ch in chunk:
            self._process_char(ch, results)
        return results

    def close(self) -> list[Any]:
        if self._errored:
            raise JSONStreamError("decoder is in error state", offset=self._offset)
        if self._closed:
            raise JSONStreamError("decoder is closed", offset=self._offset)
        # If a top-level number/literal is waiting for terminator, emit it
        if self._state == "top_term":
            value = self._decode_buffer()
            self._buffer.clear()
            self._buffer_size = 0
            self._state = "between"
            self._closed = True
            return [value]
        if self._state != "between" or self._stack:
            self._closed = True
            raise IncompleteJSONError("incomplete JSON value", offset=self._offset)
        self._closed = True
        return []

    def pending(self) -> int:
        return self._buffer_size

    # ------------------------------------------------------------------
    # Internal
    # ------------------------------------------------------------------

    def _add_to_buffer(self, ch: str) -> None:
        if self._buffer_size >= self._max_buffer:
            self._errored = True
            raise BufferLimitError(
                "value exceeds max_buffer",
                offset=self._buffer_start + self._max_buffer,
            )
        self._buffer.append(ch)
        self._buffer_size += 1

    def _decode_buffer(self) -> Any:
        text = "".join(self._buffer)
        return json.loads(text)

    def _emit_top(self, results: list[Any]) -> None:
        results.append(self._decode_buffer())
        self._buffer.clear()
        self._buffer_size = 0

    def _start_value(self, ch: str) -> None:
        """Begin a new top-level value."""
        self._buffer_start = self._offset
        self._buffer.clear()
        self._buffer_size = 0
        self._add_to_buffer(ch)

    def _validate_number_end(self) -> None:
        ns = self._num_state
        # Valid end states: 2 (after_zero), 3 (after_int), 4 (after_digits),
        # 6 (after_frac), 9 (after_exp_digits)
        if ns not in (2, 3, 4, 6, 9):
            raise JSONStreamError(
                "invalid number", offset=self._offset
            )

    def _validate_number_start(self) -> None:
        if self._num_state == 0:
            raise JSONStreamError("invalid number", offset=self._offset)

    def _is_container_number_terminator(self, ch: str) -> bool:
        """Check if ch ends a number in a container context."""
        return ch in _WHITESPACE or ch in ",]}"

    def _is_top_terminator(self, ch: str) -> bool:
        """Valid terminator for top-level number/literal."""
        return ch in _WHITESPACE or ch in '{["'

    def _container_expectation(self) -> str:
        """Return what the current container context expects."""
        if not self._stack:
            return "top"
        return self._stack[-1]

    def _expecting_value(self) -> bool:
        ctx = self._container_expectation()
        return ctx in ("array_value", "object_value")

    def _process_char(self, ch: str, results: list[Any]) -> None:
        offset = self._offset
        state = self._state

        # --- Between values (top-level and in-container) ---
        if state == "between":
            if ch in _WHITESPACE:
                self._offset += 1
                return
            # Check if we're in a container expecting a structural char
            ctx = self._container_expectation()
            if ctx == "array_after":
                # expect ',' or ']'
                if ch == ",":
                    self._stack[-1] = "array_value"
                    self._add_to_buffer(ch)
                    self._offset += 1
                    return
                if ch == "]":
                    self._add_to_buffer(ch)
                    self._stack.pop()
                    if self._stack:
                        self._stack[-1] = self._after_value_state()
                    else:
                        # top-level array/object complete
                        self._emit_top(results)
                        self._state = "between"
                    self._offset += 1
                    return
                self._errored = True
                raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)
            if ctx == "object_after":
                if ch == ",":
                    self._stack[-1] = "object_key"
                    self._add_to_buffer(ch)
                    self._offset += 1
                    return
                if ch == "}":
                    self._add_to_buffer(ch)
                    self._stack.pop()
                    if self._stack:
                        self._stack[-1] = self._after_value_state()
                    else:
                        self._emit_top(results)
                        self._state = "between"
                    self._offset += 1
                    return
                self._errored = True
                raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)
            if ctx == "object_after_key":
                if ch == ":":
                    self._stack[-1] = "object_value"
                    self._add_to_buffer(ch)
                    self._offset += 1
                    return
                self._errored = True
                raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)

            # Expecting a value: start the appropriate token
            # Check for invalid characters
            if ch in "]}:,":
                self._errored = True
                raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)
            if ch.isalpha() and ch not in "tfn":
                self._errored = True
                raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)

            # Start a value
            if self._stack:
                # container value – add to buffer
                self._add_to_buffer(ch)
                if ch == "{":
                    if len(self._stack) >= 1000:
                        self._errored = True
                        raise JSONStreamError("max nesting depth exceeded", offset=offset)
                    self._stack.append("object_key")
                elif ch == "[":
                    if len(self._stack) >= 1000:
                        self._errored = True
                        raise JSONStreamError("max nesting depth exceeded", offset=offset)
                    self._stack.append("array_value")
                elif ch == '"':
                    self._state = "string"
                elif ch == "-" or ch.isdigit():
                    self._state = "number"
                    self._num_state = 0
                    self._number_char(ch)
                elif ch == "t":
                    self._state = "literal"
                    self._lit_target = "true"
                    self._lit_pos = 1
                    if self._lit_pos >= len(self._lit_target):
                        self._finish_literal_in_container(results)
                elif ch == "f":
                    self._state = "literal"
                    self._lit_target = "false"
                    self._lit_pos = 1
                elif ch == "n":
                    self._state = "literal"
                    self._lit_target = "null"
                    self._lit_pos = 1
                else:
                    self._errored = True
                    raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)
            else:
                # top-level
                self._start_value(ch)
                if ch == "{":
                    if len(self._stack) >= 1000:
                        self._errored = True
                        raise JSONStreamError("max nesting depth exceeded", offset=offset)
                    self._stack.append("object_key")
                elif ch == "[":
                    if len(self._stack) >= 1000:
                        self._errored = True
                        raise JSONStreamError("max nesting depth exceeded", offset=offset)
                    self._stack.append("array_value")
                elif ch == '"':
                    self._state = "top_string"
                elif ch == "-" or ch.isdigit():
                    self._state = "top_number"
                    self._num_state = 0
                    self._number_char_top(ch)
                elif ch == "t":
                    self._state = "top_literal"
                    self._lit_target = "true"
                    self._lit_pos = 1
                    if self._lit_pos >= len(self._lit_target):
                        self._state = "top_term"
                elif ch == "f":
                    self._state = "top_literal"
                    self._lit_target = "false"
                    self._lit_pos = 1
                elif ch == "n":
                    self._state = "top_literal"
                    self._lit_target = "null"
                    self._lit_pos = 1
                else:
                    self._errored = True
                    raise JSONStreamError(f"unexpected character {ch!r}", offset=offset)
            self._offset += 1
            return

        # --- Top-level string ---
        if state == "top_string":
            self._process_string_char(ch, results)
            self._offset += 1
            return

        # --- Container string ---
        if state == "string":
            self._process_string_char(ch, results)
            self._offset += 1
            return

        # --- Escape ---
        if state == "escape":
            if ch in ('"', "\\", "/", "b", "f", "n", "r", "t", "u"):
                self._add_to_buffer(ch)
                if ch == "u":
                    self._state = "unicode"
                    self._unicode_count = 0
                else:
                    self._state = self._escape_target
            else:
                self._errored = True
                raise JSONStreamError(f"invalid escape character {ch!r}", offset=offset)
            self._offset += 1
            return

        # --- Unicode escape ---
        if state == "unicode":
            if ch in _HEX_DIGITS:
                self._add_to_buffer(ch)
                self._unicode_count += 1
                if self._unicode_count == 4:
                    self._state = self._escape_target
            else:
                self._errored = True
                raise JSONStreamError(
                    f"invalid unicode escape digit {ch!r}", offset=offset
                )
            self._offset += 1
            return

        # --- Top-level number ---
        if state == "top_number":
            self._process_top_number(ch, results)
            self._offset += 1
            return

        # --- Container number ---
        if state == "number":
            self._process_container_number(ch, results)
            self._offset += 1
            return

        # --- Top-level literal ---
        if state == "top_literal":
            self._process_top_literal(ch, results)
            self._offset += 1
            return

        # --- Container literal ---
        if state == "literal":
            self._process_container_literal(ch, results)
            self._offset += 1
            return

        # --- Top-level terminator ---
        if state == "top_term":
            if self._is_top_terminator(ch):
                self._emit_top(results)
                self._state = "between"
                # Re-process this char in 'between'
                self._process_char(ch, results)
            else:
                self._errored = True
                raise JSONStreamError(
                    f"invalid terminator after top-level number/literal", offset=offset
                )
            return

        self._errored = True
        raise JSONStreamError("internal decoder state error", offset=offset)

    # ------------------------------------------------------------------
    # String handling
    # ------------------------------------------------------------------

    def _process_string_char(self, ch: str, results: list[Any]) -> None:
        offset = self._offset
        if ch == '"':
            self._add_to_buffer(ch)
            if self._state == "top_string":
                self._emit_top(results)
                self._state = "between"
            else:
                # container string complete
                ctx = self._container_expectation()
                if ctx == "object_key":
                    self._stack[-1] = "object_after_key"
                else:
                    self._stack[-1] = self._after_value_state()
                self._state = "between"
            return
        if ch == "\\":
            self._add_to_buffer(ch)
            self._escape_target = self._state
            self._state = "escape"
            return
        # Control characters U+0000–U+001F are not allowed raw
        if ord(ch) < 0x20:
            self._errored = True
            raise JSONStreamError(
                "unescaped control character in string", offset=offset
            )
        self._add_to_buffer(ch)

    # ------------------------------------------------------------------
    # Number handling
    # ------------------------------------------------------------------

    def _number_char(self, ch: str) -> None:
        """Advance number sub-state. Raises on invalid char."""
        ns = self._num_state
        if ns == 0:
            # start of number
            if ch == "-":
                self._num_state = 1
            elif ch == "0":
                self._num_state = 2
            elif ch in "123456789":
                self._num_state = 3
            else:
                raise JSONStreamError("invalid number start", offset=self._offset)
        elif ns == 1:
            # after '-'
            if ch == "0":
                self._num_state = 2
            elif ch in "123456789":
                self._num_state = 3
            else:
                raise JSONStreamError("invalid number after '-'", offset=self._offset)
        elif ns == 2:
            # after '0' – can see '.', 'e', 'E', or terminator
            self._num_state = 4  # treat as after_digits for '.'
            self._number_char(ch)
            # Re-check: after 0, only ., e, E valid
            # This recursive approach is tricky; let me handle it inline
            return
        elif ns == 3:
            # after first digit 1-9
            if ch.isdigit():
                self._num_state = 4
            elif ch == ".":
                self._num_state = 5
            elif ch in "eE":
                self._num_state = 7
            else:
                raise JSONStreamError("invalid number", offset=self._offset)
        elif ns == 4:
            # after digits
            if ch.isdigit():
                self._num_state = 4
            elif ch == ".":
                self._num_state = 5
            elif ch in "eE":
                self._num_state = 7
            else:
                raise JSONStreamError("invalid number", offset=self._offset)
        elif ns == 5:
            # after '.'
            if ch.isdigit():
                self._num_state = 6
            else:
                raise JSONStreamError("invalid number after '.'", offset=self._offset)
        elif ns == 6:
            # after fraction digits
            if ch.isdigit():
                self._num_state = 6
            elif ch in "eE":
                self._num_state = 7
            else:
                raise JSONStreamError("invalid number", offset=self._offset)
        elif ns == 7:
            # after 'e'/'E'
            if ch in "+-":
                self._num_state = 8
            elif ch.isdigit():
                self._num_state = 9
            else:
                raise JSONStreamError("invalid number after 'e'", offset=self._offset)
        elif ns == 8:
            # after exponent sign
            if ch.isdigit():
                self._num_state = 9
            else:
                raise JSONStreamError("invalid number in exponent", offset=self._offset)
        elif ns == 9:
            # after exponent digits
            if ch.isdigit():
                self._num_state = 9
            else:
                raise JSONStreamError("invalid number", offset=self._offset)

    def _number_char_top(self, ch: str) -> None:
        self._num_state = 0
        self._number_char(ch)

    def _process_top_number(self, ch: str, results: list[Any]) -> None:
        """Process a character in top-level number state."""
        offset = self._offset
        ns = self._num_state
        # Try to continue the number
        if ns == 2:
            # after '0': valid continuations are '.', 'e', 'E'
            if ch in ".eE":
                self._add_to_buffer(ch)
                if ch == ".":
                    self._num_state = 5
                else:
                    self._num_state = 7
                return
            # terminator
            self._validate_number_end()
            if self._is_top_terminator(ch):
                self._emit_top(results)
                self._state = "between"
                self._process_char(ch, results)
            else:
                self._errored = True
                raise JSONStreamError("invalid terminator", offset=offset)
            return
        # Try continuing
        try:
            self._add_to_buffer(ch)
            self._number_char(ch)
        except JSONStreamError:
            # The char doesn't continue the number – it's a terminator
            self._buffer.pop()
            self._buffer_size -= 1
            self._validate_number_end()
            if self._is_top_terminator(ch):
                self._emit_top(results)
                self._state = "between"
                self._process_char(ch, results)
            else:
                self._errored = True
                raise JSONStreamError("invalid terminator", offset=offset)

    def _process_container_number(self, ch: str, results: list[Any]) -> None:
        """Process a character in container number state."""
        offset = self._offset
        ns = self._num_state
        if ns == 2:
            if ch in ".eE":
                self._add_to_buffer(ch)
                if ch == ".":
                    self._num_state = 5
                else:
                    self._num_state = 7
                return
            # terminator
            self._validate_number_end()
            self._state = "between"
            self._process_char(ch, results)
            return
        try:
            self._add_to_buffer(ch)
            self._number_char(ch)
        except JSONStreamError:
            self._buffer.pop()
            self._buffer_size -= 1
            self._validate_number_end()
            self._state = "between"
            self._process_char(ch, results)

    # ------------------------------------------------------------------
    # Literal handling
    # ------------------------------------------------------------------

    def _process_top_literal(self, ch: str, results: list[Any]) -> None:
        offset = self._offset
        if self._lit_pos < len(self._lit_target) and ch == self._lit_target[self._lit_pos]:
            self._add_to_buffer(ch)
            self._lit_pos += 1
            if self._lit_pos >= len(self._lit_target):
                self._state = "top_term"
        else:
            self._errored = True
            raise JSONStreamError(f"invalid literal", offset=offset)

    def _process_container_literal(self, ch: str, results: list[Any]) -> None:
        offset = self._offset
        if self._lit_pos < len(self._lit_target) and ch == self._lit_target[self._lit_pos]:
            self._add_to_buffer(ch)
            self._lit_pos += 1
            if self._lit_pos >= len(self._lit_target):
                # literal complete in container
                self._stack[-1] = self._after_value_state()
                self._state = "between"
        else:
            self._errored = True
            raise JSONStreamError("invalid literal", offset=offset)

    def _finish_literal_in_container(self, results: list[Any]) -> None:
        """Called when a single-char literal is complete (shouldn't happen in JSON)."""
        # All JSON literals are multi-char; this is a safety net
        self._stack[-1] = self._after_value_state()
        self._state = "between"

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------

    def _after_value_state(self) -> str:
        """Return the after-value state for the current top container."""
        if self._stack:
            # Check if we're in an object (look deeper)
            # The stack stores current state; after a value in array → array_after
            # after a value in object → object_after
            # We need to know which type the current container is
            # Since we set the state when entering, array_value → array_after, object_value → object_after
            top = self._stack[-1]
            if top in ("array_value", "array_after"):
                return "array_after"
            else:
                return "object_after"
        return "top"
