### test_solution.py
```python
import pytest
import solution
from solution import (
    JSONStreamDecoder,
    JSONStreamError,
    IncompleteJSONError,
    BufferLimitError,
)


# ─── Basic values ───────────────────────────────────────────────────────────

class TestBasicValues:
    def test_empty_feed(self):
        d = JSONStreamDecoder()
        assert d.feed("") == []
        assert d.close() == []

    def test_integer(self):
        d = JSONStreamDecoder()
        assert d.feed("42 ") == [42]
        assert d.close() == []

    def test_negative_integer(self):
        d = JSONStreamDecoder()
        assert d.feed("-7 ") == [-7]
        assert d.close() == []

    def test_float(self):
        d = JSONStreamDecoder()
        assert d.feed("3.14 ") == [3.14]

    def test_exponent(self):
        d = JSONStreamDecoder()
        assert d.feed("1e10 ") == [1e10]

    def test_true(self):
        d = JSONStreamDecoder()
        assert d.feed("true ") == [True]

    def test_false(self):
        d = JSONStreamDecoder()
        assert d.feed("false ") == [False]

    def test_null(self):
        d = JSONStreamDecoder()
        assert d.feed("null ") == [None]

    def test_string(self):
        d = JSONStreamDecoder()
        assert d.feed('"hello"') == ["hello"]

    def test_empty_object(self):
        d = JSONStreamDecoder()
        assert d.feed("{}") == [{}]

    def test_empty_array(self):
        d = JSONStreamDecoder()
        assert d.feed("[]") == [[]]

    def test_nested_object(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a": [1, 2, {"b": 3}]}') == [{"a": [1, 2, {"b": 3}]}]

    def test_unicode_escape(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\u00e9"') == ["é"]

    def test_surrogate_pair(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\ud83d\\ude00"') == ["\U0001f600"]

    def test_lone_surrogate(self):
        d = JSONStreamDecoder()
        # Lone surrogate escape is accepted (syntax only)
        r = d.feed('"\\ud800"')
        assert len(r) == 1
        assert r[0] == "\ud800"

    def test_all_escapes(self):
        d = JSONStreamDecoder()
        assert d.feed(r'"\\\"\/\b\f\n\r\t"') == ["\"/\x08\x0c\n\r\t"]

    def test_large_int(self):
        d = JSONStreamDecoder()
        big = str(10**100)
        assert d.feed(big + " ") == [int(big)]

    def test_negative_zero_float(self):
        d = JSONStreamDecoder()
        r = d.feed("-0.0 ")
        assert r == [-0.0]
        assert r[0] == -0.0
        import math
        assert math.copysign(1, r[0]) == -1

    def test_overflow_float(self):
        d = JSONStreamDecoder()
        import math
        r = d.feed("1E400 ")
        assert r == [math.inf]

    def test_duplicate_key(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a":1,"a":2}') == [{"a": 2}]

    def test_key_order(self):
        d = JSONStreamDecoder()
        r = d.feed('{"b":1,"a":2,"c":3}')
        assert list(r[0].keys()) == ["b", "a", "c"]


# ─── Multiple values per feed ──────────────────────────────────────────────

class TestMultipleValues:
    def test_multiple_objects(self):
        d = JSONStreamDecoder()
        assert d.feed('{} [] "x"') == [{}, [], "x"]

    def test_no_whitespace_separation(self):
        d = JSONStreamDecoder()
        assert d.feed('{}[]"x"') == [{}, [], "x"]

    def test_1_2_space(self):
        d = JSONStreamDecoder()
        assert d.feed("1 2 ") == [1, 2]

    def test_12_one_number(self):
        d = JSONStreamDecoder()
        # "12 " → 12 is terminated by space
        assert d.feed("12 ") == [12]

    def test_12_no_terminator(self):
        d = JSONStreamDecoder()
        assert d.feed("12") == []  # 12 not terminated yet
        assert d.close() == [12]

    def test_number_followed_by_object(self):
        d = JSONStreamDecoder()
        assert d.feed("1[2]") == [1, [2]]

    def test_true_followed_by_string(self):
        d = JSONStreamDecoder()
        assert d.feed('true"x"') == [True, "x"]

    def test_number_followed_by_array(self):
        d = JSONStreamDecoder()
        assert d.feed("7[1,2]") == [7, [1, 2]]

    def test_heartbeat_values(self):
        d = JSONStreamDecoder()
        assert d.feed("7 true ") == [7, True]


# ─── Chunked delivery ──────────────────────────────────────────────────────

class TestChunkedDelivery:
    def test_string_split(self):
        d = JSONStreamDecoder()
        assert d.feed('"hel') == []
        assert d.feed('lo"') == ["hello"]

    def test_escape_split(self):
